/// Detection and redaction for one configuration.
#[derive(Clone)]
#[wasm_bindgen]
pub struct WasmPiiPipeline {
    pub(crate) inner: Arc<hacienda::pii::PiiPipeline>,
}

#[wasm_bindgen]
impl WasmPiiPipeline {
    /// Return an independent handle for an ownership-taking API.
    ///
    /// Use `copyForTransfer()` for each class value placed in an array when the original
    /// handle must remain usable.
    #[wasm_bindgen(js_name = "copyForTransfer")]
    pub fn copy_for_transfer(&self) -> WasmPiiPipeline {
        self.clone()
    }

    /// Build a pipeline, loading the NER backend named by the configuration.
    ///
    /// # Errors
    ///
    /// Returns `PiiError.Pattern` if a built-in pattern fails to compile,
    /// `PiiError.Ner` if the model cannot be loaded, and
    /// `PiiError.ModelUnavailable` if the configuration enables a model this
    /// build cannot load.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen]
    pub fn new(config: WasmPipelineConfig) -> Result<WasmPiiPipeline, JsValue> {
        let result = hacienda::pii::PiiPipeline::new(config.into()).map_err(alef_wasm_err)?;
        Ok(Self {
            inner: Arc::new(result),
        })
    }

    /// Build a pipeline around a caller-supplied detector.
    ///
    /// This is the entry point for backends that are not loaded from a local model
    /// directory — a WASM bridge, a remote service, or a test double.
    ///
    /// # Errors
    ///
    /// Returns `PiiError.Pattern` if a built-in pattern fails to compile.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen(js_name = "withDetector")]
    pub fn with_detector(
        config: WasmPipelineConfig,
        detector: Option<WasmNerDetector>,
    ) -> Result<WasmPiiPipeline, JsValue> {
        let result = hacienda::pii::PiiPipeline::with_detector(config.into(), detector.as_ref().map(|v| &v.inner))
            .map_err(alef_wasm_err)?;
        Ok(Self {
            inner: Arc::new(result),
        })
    }

    /// `PiiPipeline.new`, plus the key set needed to mint reversible pseudonym tokens.
    ///
    /// Required when the configuration selects
    /// `RedactionMode.Pseudonymize`;
    /// `new` and `with_detector` pass `None` and will fail for that mode rather than
    /// quietly masking instead.
    ///
    /// The `Arc` is shared rather than cloned per pipeline: every pipeline in a batch run
    /// must mint the same token for the same value, or cross-document co-reference — the
    /// point of the mode — breaks.
    ///
    /// # Errors
    ///
    /// As `PiiPipeline.new`, plus
    /// `RedactionError.MissingPseudonymKey`
    /// if the mode needs a key and `pseudonymiser` is `None`.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen(js_name = "withPseudonymiser")]
    pub fn with_pseudonymiser(
        config: WasmPipelineConfig,
        pseudonymiser: Option<WasmPseudonymiser>,
    ) -> Result<WasmPiiPipeline, JsValue> {
        let result =
            hacienda::pii::PiiPipeline::with_pseudonymiser(config.into(), pseudonymiser.as_ref().map(|v| &v.inner))
                .map_err(alef_wasm_err)?;
        Ok(Self {
            inner: Arc::new(result),
        })
    }

    /// `PiiPipeline.with_detector`, plus the pseudonymisation key set.
    ///
    /// # Errors
    ///
    /// As `PiiPipeline.with_pseudonymiser`, without the model-loading failures.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen(js_name = "withDetectorAndPseudonymiser")]
    pub fn with_detector_and_pseudonymiser(
        config: WasmPipelineConfig,
        detector: Option<WasmNerDetector>,
        pseudonymiser: Option<WasmPseudonymiser>,
    ) -> Result<WasmPiiPipeline, JsValue> {
        let result = hacienda::pii::PiiPipeline::with_detector_and_pseudonymiser(
            config.into(),
            detector.as_ref().map(|v| &v.inner),
            pseudonymiser.as_ref().map(|v| &v.inner),
        )
        .map_err(alef_wasm_err)?;
        Ok(Self {
            inner: Arc::new(result),
        })
    }

    #[wasm_bindgen]
    pub fn config(&self) -> WasmPipelineConfig {
        self.inner.config().clone().into()
    }

    /// True when a NER backend is loaded. A `false` here means regex-only detection.
    #[wasm_bindgen(js_name = "hasModel")]
    pub fn has_model(&self) -> bool {
        self.inner.has_model()
    }

    /// Detect and redact.
    ///
    /// # Errors
    ///
    /// Returns `PiiError.Ner` if the NER backend fails. Detection failures are not
    /// swallowed: returning partially-detected text as if it were redacted would leak PII.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen]
    pub async fn process(&self, text: String) -> Result<WasmPipelineResult, JsValue> {
        let result = self.inner.process(&text).await.map_err(alef_wasm_err)?;
        Ok(result.into())
    }

    /// Detect without rewriting the text.
    ///
    /// # Errors
    ///
    /// Returns `PiiError.Ner` if the NER backend fails.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen]
    pub async fn scan(&self, text: String) -> Result<WasmPipelineResult, JsValue> {
        let result = self.inner.scan(&text).await.map_err(alef_wasm_err)?;
        Ok(result.into())
    }

    /// Detect and redact using pre-computed model entities, bypassing the NER detector.
    ///
    /// This allows callers who have already run NER inference (e.g., for an entity glossary)
    /// to reuse those results instead of running inference a second time.
    ///
    /// # Errors
    ///
    /// Returns `PiiError.Ner` if regex detection fails, or
    /// `PiiError.InvalidModelEntity` if any pre-computed model entity fails
    /// validation (see `validate_model_entity`).
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen(js_name = "processWithModelEntities")]
    pub async fn process_with_model_entities(
        &self,
        text: String,
        model_entities: Vec<WasmModelEntity>,
    ) -> Result<WasmPipelineResult, JsValue> {
        let result = self
            .inner
            .process_with_model_entities(&text, model_entities)
            .await
            .map_err(alef_wasm_err)?;
        Ok(result.into())
    }

    /// Detect without rewriting the text, using pre-computed model entities.
    ///
    /// See `process_with_model_entities` for details.
    #[allow(clippy::missing_errors_doc)]
    #[wasm_bindgen(js_name = "scanWithModelEntities")]
    pub async fn scan_with_model_entities(
        &self,
        text: String,
        model_entities: Vec<WasmModelEntity>,
    ) -> Result<WasmPipelineResult, JsValue> {
        let result = self
            .inner
            .scan_with_model_entities(&text, model_entities)
            .await
            .map_err(alef_wasm_err)?;
        Ok(result.into())
    }
}

