/// Compute the chain hash linking an entry to its predecessor.
///
/// The timestamp is deliberately excluded so verification is reproducible.
#[wasm_bindgen(js_name = "computeChainHash")]
pub fn compute_chain_hash(prev_chain_hash: String, seq: u64, fields: WasmChainHashFields) -> String {
    let fields_core: hacienda::audit::ChainHashFields = fields.into();

    hacienda::audit::compute_chain_hash(&prev_chain_hash, seq, fields_core)
}

/// Compute the blake3 hash that seals a segment's metadata.
///
/// Every field is length-prefixed before being fed to the hasher. This prevents
/// ambiguous splits: without length prefixes, `("ab", "c")` and `("a", "bc")` would
/// produce the same byte sequence. `compute_chain_hash` in `entry.rs` uses fixed-width
/// integers (which are self-delimiting) alongside string bytes and does not need this
/// guard, but the seal fields are all variable-length strings, so it is required here.
///
/// The field order and encoding here is the canonical definition of the seal hash for
/// this crate. Changing either breaks all stored seals.
///
/// The nine arguments map one-to-one to the nine `SegmentSeal` fields that the hash
/// covers. Wrapping them in a struct would force callers to construct one just to call this
/// function; keeping them flat is both more legible and consistent with `compute_chain_hash`.
#[allow(clippy::too_many_arguments)]
#[wasm_bindgen(js_name = "computeSealHash")]
pub fn compute_seal_hash(
    prev_seal_hash: Option<String>,
    segment_id: String,
    tenant_id: String,
    node_id: String,
    config_hash: String,
    sealed_tip: String,
    entry_count: u64,
    opened_at: String,
    sealed_at: String,
) -> String {
    hacienda::audit::compute_seal_hash(
        prev_seal_hash.as_deref(),
        &segment_id,
        &tenant_id,
        &node_id,
        &config_hash,
        &sealed_tip,
        entry_count,
        &opened_at,
        &sealed_at,
    )
}

/// Boost each entity's confidence toward `1.0` when one of its category's context words
/// (`entity.context_words`, set by `find_all` from the
/// originating `PatternMeta`) appears within `PREFIX_WORDS` tokens
/// before or `SUFFIX_WORDS` tokens after its span in `text`.
///
/// A no-op for an entity that's already at `1.0` (nothing to boost) or that has no
/// context words calibrated for its category.
#[wasm_bindgen]
pub fn enhance(entities: Vec<WasmRegexEntity>, text: String) -> () {
    let entities_core: Vec<_> = entities.into_iter().map(Into::into).collect();

    hacienda::pii::context::enhance(&entities_core, &text)
}

/// Luhn (mod-10) check over the digit characters of `s`.
#[wasm_bindgen(js_name = "luhnValid")]
pub fn luhn_valid(s: String) -> bool {
    hacienda::pii::validators::luhn_valid(&s)
}

/// Reconcile regex and model detections into a single non-overlapping, offset-ordered list.
///
/// Two spans are treated as the same detection when their overlap ratio exceeds
/// `config.overlap_threshold`; the winner is chosen by `config.priority`.
#[wasm_bindgen(js_name = "mergeEntities")]
pub fn merge_entities(
    regex_entities: Vec<WasmRegexEntity>,
    model_entities: Vec<WasmModelEntity>,
    config: WasmMergeConfig,
) -> Vec<WasmMergedEntity> {
    let regex_entities_core: Vec<_> = regex_entities.into_iter().map(Into::into).collect();

    let model_entities_core: Vec<_> = model_entities.into_iter().map(Into::into).collect();

    let config_core: hacienda::pii::MergeConfig = config.into();

    hacienda::pii::merge_entities(regex_entities_core, model_entities_core, &config_core)
        .into_iter()
        .map(Into::into)
        .collect()
}

