/// Compose the common capability report from surface-specific runtime checks.
///
/// `ner` must come from the detector the reporting surface actually uses. Passing
/// `NerRuntimeState.unavailable()` is honest for a surface that never built a
/// facade; reading a process-global model id here would let one surface's model
/// leak into another surface's report.
#[wasm_bindgen]
pub fn report(
    version: String,
    embedding_compiled: bool,
    onnx_runtime: WasmCapabilityStatus,
    service_ready: bool,
    ner: WasmNerRuntimeState,
) -> WasmCapabilityReport {
    let onnx_runtime_core: hacienda::capabilities::CapabilityStatus = onnx_runtime.into();

    let ner_core: hacienda::pii::NerRuntimeState = ner.into();

    hacienda::capabilities::report(&version, embedding_compiled, onnx_runtime_core, service_ready, ner_core).into()
}

